{
  "contract": "X7RLiquidityHub",
  "closure": {
    "site_function": "sendTreasuryBalance",
    "site_call": ".call",
    "functions": [
      "sendTreasuryBalance",
      "sendDistributeBalance",
      "processFees"
    ],
    "justification": "These functions interact with the exposed storage variables _ethBal and treasuryBalance, and are relevant to the target property."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "sendDistributeBalance",
      "processFees"
    ],
    "nesting_bound": {
      "sendTreasuryBalance": 1
    }
  },
  "phases": {
    "function": "sendTreasuryBalance",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .call",
      "to_marker": "after .call"
    },
    "post": {
      "name": "post",
      "from_marker": "after .call",
      "to_marker": "exit"
    },
    "linearization_point": "after .call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in-flight during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "distributeBalance + treasuryBalance + liquidityBalance + inFlight <= _ethBal",
    "stable_formula": "distributeBalance + treasuryBalance + liquidityBalance <= _ethBal",
    "kind": "additive"
  },
  "composition": {
    "target_property": "distributeBalance + treasuryBalance + liquidityBalance <= _ethBal",
    "rule": "The exposure invariant ensures that the sum of balances does not exceed the ETH balance even during reentrant calls."
  }
}
